-- P02 Training Management: initial schema.
-- Source: docs/database/proposed-schema.sql (comments removed; statements unchanged).
-- Do not edit this file after it has been applied. Make changes in a new migration.


-- 1. users
CREATE TABLE users (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    username            VARCHAR(50)  NOT NULL,
    email               VARCHAR(255) NOT NULL,
    password_hash       VARCHAR(60)  NOT NULL,
    full_name           VARCHAR(255) NOT NULL,
    role                VARCHAR(20)  NOT NULL,
    is_active           BOOLEAN      NOT NULL DEFAULT TRUE,
    failed_login_count  INT          NOT NULL DEFAULT 0,
    locked_until        TIMESTAMPTZ,
    token_version       INT          NOT NULL DEFAULT 0,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT ck_users_role CHECK (role IN
        ('TRAINING_ADMIN', 'TRAINING_MANAGER', 'INSTRUCTOR', 'STUDENT'))
);
CREATE UNIQUE INDEX uq_users_username_lower ON users (LOWER(username));
CREATE UNIQUE INDEX uq_users_email_lower    ON users (LOWER(email));
CREATE INDEX ix_users_role_active ON users (role, is_active);


-- 2. student
CREATE TABLE student (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    user_id         BIGINT      NOT NULL,
    student_code    VARCHAR(30) NOT NULL,
    date_of_birth   DATE,
    homeroom_class  VARCHAR(50),
    status          VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_student PRIMARY KEY (id),
    CONSTRAINT uq_student_user UNIQUE (user_id),
    CONSTRAINT uq_student_code UNIQUE (student_code),
    CONSTRAINT fk_student_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT ck_student_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'INACTIVE'))
);


-- 3. instructor
CREATE TABLE instructor (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    user_id          BIGINT      NOT NULL,
    instructor_code  VARCHAR(30) NOT NULL,
    department       VARCHAR(100),
    phone            VARCHAR(20),
    is_active        BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_instructor PRIMARY KEY (id),
    CONSTRAINT uq_instructor_user UNIQUE (user_id),
    CONSTRAINT uq_instructor_code UNIQUE (instructor_code),
    CONSTRAINT fk_instructor_user FOREIGN KEY (user_id) REFERENCES users (id)
);


-- 4. course
CREATE TABLE course (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code                VARCHAR(20)  NOT NULL,
    name                VARCHAR(150) NOT NULL,
    credits             INT          NOT NULL,
    duration_hours      INT          NOT NULL,
    min_attendance_pct  NUMERIC(5,2) NOT NULL DEFAULT 80,
    pass_score          NUMERIC(4,2) NOT NULL DEFAULT 5.0,
    midterm_weight      NUMERIC(3,2) NOT NULL DEFAULT 0.40,
    final_weight        NUMERIC(3,2) NOT NULL DEFAULT 0.60,
    is_active           BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_course PRIMARY KEY (id),
    CONSTRAINT uq_course_code UNIQUE (code),
    CONSTRAINT ck_course_weights_sum CHECK (midterm_weight + final_weight = 1),
    CONSTRAINT ck_course_midterm_weight CHECK (midterm_weight BETWEEN 0 AND 1),
    CONSTRAINT ck_course_final_weight CHECK (final_weight BETWEEN 0 AND 1),
    CONSTRAINT ck_course_credits CHECK (credits > 0),
    CONSTRAINT ck_course_duration CHECK (duration_hours > 0),
    CONSTRAINT ck_course_min_attendance CHECK (min_attendance_pct BETWEEN 0 AND 100),
    CONSTRAINT ck_course_pass_score CHECK (pass_score BETWEEN 0 AND 10)
);


-- 5. instructor_course
CREATE TABLE instructor_course (
    instructor_id  BIGINT NOT NULL,
    course_id      BIGINT NOT NULL,

    CONSTRAINT pk_instructor_course PRIMARY KEY (instructor_id, course_id),
    CONSTRAINT fk_ic_instructor FOREIGN KEY (instructor_id) REFERENCES instructor (id),
    CONSTRAINT fk_ic_course FOREIGN KEY (course_id) REFERENCES course (id) ON DELETE CASCADE
);
CREATE INDEX ix_instructor_course_course ON instructor_course (course_id);


-- 6. room
CREATE TABLE room (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code        VARCHAR(30) NOT NULL,
    capacity    INT         NOT NULL,
    is_active   BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_room PRIMARY KEY (id),
    CONSTRAINT uq_room_code UNIQUE (code),
    CONSTRAINT ck_room_capacity CHECK (capacity >= 1)
);


-- 7. class_offering
CREATE TABLE class_offering (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    class_code          VARCHAR(30)  NOT NULL,
    course_id           BIGINT       NOT NULL,
    semester            VARCHAR(20)  NOT NULL,
    start_date          DATE         NOT NULL,
    end_date            DATE         NOT NULL,
    instructor_id       BIGINT,
    max_capacity        INT          NOT NULL,
    enrolled_count      INT          NOT NULL DEFAULT 0,
    status              VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    cancel_deadline     TIMESTAMPTZ  NOT NULL,
    cancel_reason       TEXT,
    created_by          BIGINT       NOT NULL,
    deleted_at          TIMESTAMPTZ,

    min_attendance_pct  NUMERIC(5,2),
    pass_score          NUMERIC(4,2),
    midterm_weight      NUMERIC(3,2),
    final_weight        NUMERIC(3,2),

    grading_status      VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    submitted_at        TIMESTAMPTZ,
    submitted_by        BIGINT,
    confirmed_at        TIMESTAMPTZ,
    confirmed_by        BIGINT,
    return_reason       TEXT,
    grading_version     INT          NOT NULL DEFAULT 0,
    started_at          TIMESTAMPTZ,
    closed_at           TIMESTAMPTZ,
    closed_by           BIGINT,
    version             INT          NOT NULL DEFAULT 0,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_class_offering PRIMARY KEY (id),
    CONSTRAINT uq_class_offering_code UNIQUE (class_code),
    CONSTRAINT fk_co_course FOREIGN KEY (course_id) REFERENCES course (id),
    CONSTRAINT fk_co_instructor FOREIGN KEY (instructor_id) REFERENCES instructor (id),
    CONSTRAINT fk_co_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_co_submitted_by FOREIGN KEY (submitted_by) REFERENCES users (id),
    CONSTRAINT fk_co_confirmed_by FOREIGN KEY (confirmed_by) REFERENCES users (id),
    CONSTRAINT fk_co_closed_by FOREIGN KEY (closed_by) REFERENCES users (id),

    CONSTRAINT ck_co_enrolled_count CHECK (enrolled_count >= 0 AND enrolled_count <= max_capacity),
    CONSTRAINT ck_co_status CHECK (status IN
        ('DRAFT', 'OPEN', 'IN_PROGRESS', 'CLOSED', 'CANCELLED')),
    CONSTRAINT ck_co_grading_status CHECK (grading_status IN
        ('DRAFT', 'SUBMITTED', 'CONFIRMED')),
    CONSTRAINT ck_co_max_capacity CHECK (max_capacity BETWEEN 1 AND 500),
    CONSTRAINT ck_co_dates CHECK (end_date > start_date),
    CONSTRAINT ck_co_cancel_deadline CHECK (
        (cancel_deadline AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= start_date),
    CONSTRAINT ck_co_snapshot_weights CHECK (
        midterm_weight IS NULL OR final_weight IS NULL OR midterm_weight + final_weight = 1),
    CONSTRAINT ck_co_snapshot_present CHECK (
        status NOT IN ('OPEN', 'IN_PROGRESS', 'CLOSED')
        OR (min_attendance_pct IS NOT NULL AND pass_score IS NOT NULL
            AND midterm_weight IS NOT NULL AND final_weight IS NOT NULL)),
    CONSTRAINT ck_co_instructor_present CHECK (
        status NOT IN ('OPEN', 'IN_PROGRESS', 'CLOSED') OR instructor_id IS NOT NULL),
    CONSTRAINT ck_co_cancel_reason CHECK (status <> 'CANCELLED' OR cancel_reason IS NOT NULL),
    CONSTRAINT ck_co_started CHECK (status NOT IN ('IN_PROGRESS', 'CLOSED') OR started_at IS NOT NULL),
    CONSTRAINT ck_co_closed CHECK (status <> 'CLOSED' OR (closed_at IS NOT NULL AND closed_by IS NOT NULL)),
    CONSTRAINT ck_co_closed_confirmed CHECK (status <> 'CLOSED' OR grading_status = 'CONFIRMED'),
    CONSTRAINT ck_co_confirmed CHECK (grading_status <> 'CONFIRMED'
        OR (confirmed_at IS NOT NULL AND confirmed_by IS NOT NULL))
);
CREATE INDEX ix_co_course ON class_offering (course_id);
CREATE INDEX ix_co_instructor_status ON class_offering (instructor_id, status);
CREATE INDEX ix_co_status_start ON class_offering (status, start_date);
CREATE INDEX ix_co_semester ON class_offering (semester);


-- 8. session
CREATE TABLE session (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    class_id            BIGINT  NOT NULL,
    session_date        DATE    NOT NULL,
    start_time          TIME    NOT NULL,
    end_time            TIME    NOT NULL,
    room_id             BIGINT  NOT NULL,
    topic               VARCHAR(200),
    attendance_locked   BOOLEAN NOT NULL DEFAULT FALSE,
    locked_by           BIGINT,
    locked_at           TIMESTAMPTZ,
    unlock_reason       TEXT,
    attendance_version  INT     NOT NULL DEFAULT 0,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_session PRIMARY KEY (id),
    CONSTRAINT fk_session_class FOREIGN KEY (class_id) REFERENCES class_offering (id),
    CONSTRAINT fk_session_room FOREIGN KEY (room_id) REFERENCES room (id),
    CONSTRAINT fk_session_locked_by FOREIGN KEY (locked_by) REFERENCES users (id),
    CONSTRAINT ck_session_time CHECK (start_time < end_time),
    CONSTRAINT ck_session_locked CHECK (NOT attendance_locked
        OR (locked_by IS NOT NULL AND locked_at IS NOT NULL))
);
CREATE INDEX ix_session_class_date ON session (class_id, session_date);
CREATE INDEX ix_session_room_date ON session (room_id, session_date);


-- 9. enrollment
CREATE TABLE enrollment (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    student_id    BIGINT      NOT NULL,
    class_id      BIGINT      NOT NULL,
    status        VARCHAR(20) NOT NULL,
    enrolled_at   TIMESTAMPTZ NOT NULL,
    cancelled_at  TIMESTAMPTZ,
    completed_at  TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_enrollment PRIMARY KEY (id),
    CONSTRAINT uq_enrollment_student_class UNIQUE (student_id, class_id),
    CONSTRAINT fk_enrollment_student FOREIGN KEY (student_id) REFERENCES student (id),
    CONSTRAINT fk_enrollment_class FOREIGN KEY (class_id) REFERENCES class_offering (id),
    CONSTRAINT ck_enrollment_status CHECK (status IN ('ENROLLED', 'CANCELLED', 'COMPLETED')),
    CONSTRAINT ck_enrollment_cancelled CHECK (
        (status = 'CANCELLED') = (cancelled_at IS NOT NULL)),
    CONSTRAINT ck_enrollment_completed CHECK (
        (status = 'COMPLETED') = (completed_at IS NOT NULL))
);
CREATE INDEX ix_enrollment_class_status ON enrollment (class_id, status);


-- 10. attendance
CREATE TABLE attendance (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    session_id  BIGINT      NOT NULL,
    student_id  BIGINT      NOT NULL,
    status      VARCHAR(10) NOT NULL,
    remarks     VARCHAR(255),
    marked_by   BIGINT      NOT NULL,
    marked_at   TIMESTAMPTZ NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_attendance PRIMARY KEY (id),
    CONSTRAINT uq_attendance_session_student UNIQUE (session_id, student_id),
    CONSTRAINT fk_attendance_session FOREIGN KEY (session_id) REFERENCES session (id),
    CONSTRAINT fk_attendance_student FOREIGN KEY (student_id) REFERENCES student (id),
    CONSTRAINT fk_attendance_marked_by FOREIGN KEY (marked_by) REFERENCES users (id),
    CONSTRAINT ck_attendance_status CHECK (status IN ('PRESENT', 'ABSENT', 'LATE'))
);


-- 11. assessment_result
CREATE TABLE assessment_result (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    student_id       BIGINT       NOT NULL,
    class_id         BIGINT       NOT NULL,
    midterm_score    NUMERIC(4,2),
    final_score      NUMERIC(4,2),
    total_score      NUMERIC(4,2),
    attendance_rate  NUMERIC(5,2),
    final_status     VARCHAR(20)  NOT NULL DEFAULT 'IN_PROGRESS',
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_assessment_result PRIMARY KEY (id),
    CONSTRAINT uq_ar_student_class UNIQUE (student_id, class_id),
    CONSTRAINT fk_ar_enrollment FOREIGN KEY (student_id, class_id)
        REFERENCES enrollment (student_id, class_id),
    CONSTRAINT ck_ar_midterm CHECK (midterm_score BETWEEN 0 AND 10),
    CONSTRAINT ck_ar_final CHECK (final_score BETWEEN 0 AND 10),
    CONSTRAINT ck_ar_total CHECK (total_score BETWEEN 0 AND 10),
    CONSTRAINT ck_ar_attendance_rate CHECK (attendance_rate BETWEEN 0 AND 100),
    CONSTRAINT ck_ar_final_status CHECK (final_status IN ('IN_PROGRESS', 'PASSED', 'FAILED'))
);
CREATE INDEX ix_ar_class ON assessment_result (class_id);


-- 12. grade_audit_log
CREATE TABLE grade_audit_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    student_id  BIGINT      NOT NULL,
    class_id    BIGINT      NOT NULL,
    score_type  VARCHAR(10) NOT NULL,
    old_score   NUMERIC(4,2),
    new_score   NUMERIC(4,2),
    changed_by  BIGINT      NOT NULL,
    reason      TEXT,
    ip_address  VARCHAR(45),
    changed_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_grade_audit_log PRIMARY KEY (id),
    CONSTRAINT fk_gal_enrollment FOREIGN KEY (student_id, class_id)
        REFERENCES enrollment (student_id, class_id),
    CONSTRAINT fk_gal_changed_by FOREIGN KEY (changed_by) REFERENCES users (id),
    CONSTRAINT ck_gal_score_type CHECK (score_type IN ('MIDTERM', 'FINAL')),
    CONSTRAINT ck_gal_old_score CHECK (old_score BETWEEN 0 AND 10),
    CONSTRAINT ck_gal_new_score CHECK (new_score BETWEEN 0 AND 10),
    CONSTRAINT ck_gal_reason CHECK (old_score IS NULL OR reason IS NOT NULL)
);
CREATE INDEX ix_gal_class_changed ON grade_audit_log (class_id, changed_at DESC);
CREATE INDEX ix_gal_changed ON grade_audit_log (changed_at DESC);


-- 13. app_security_log
CREATE TABLE app_security_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    action      VARCHAR(30) NOT NULL,
    username    VARCHAR(50),
    ip_address  VARCHAR(45),
    details     JSONB,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pk_app_security_log PRIMARY KEY (id)
);
CREATE INDEX ix_asl_action_created ON app_security_log (action, created_at DESC);
CREATE INDEX ix_asl_created ON app_security_log (created_at DESC);
